// Единый формат входа {channel, chat_id, text, callback_data} — задел под Instagram-адаптер (Фаза 2).
const u = $json;
const msg = u.message || (u.callback_query ? u.callback_query.message : null);
if (!msg) return [];
const chat = msg.chat;
return [{ json: { channel: 'telegram', chat_id: String(chat.id), first_name: chat.first_name || chat.title || '', text: (u.message && u.message.text ? u.message.text : '').trim(), callback_data: u.callback_query ? (u.callback_query.data || '') : '' } }];

// Ядро state machine: текущее состояние + входящее сообщение → маршрут.
const norm = $('🧩 Нормализовать вход').first().json;
const lead = $('🔎 Лид + состояние').first().json;
const text = (norm.text || '').toLowerCase();
const cb = norm.callback_data;
const orderIntent = (/(хочу|нужен|нужна|закаж|заказать|оформ)/.test(text) && /(аудит|заказ)/.test(text)) || text === '/order' || text === '/start_order';
const yes = /^(да|согласен|согласна|подтверждаю|ок|ok)\b/.test(text);
let route = 'faq';
if (cb === 'start_order') route = 'start_questionnaire';
else if (cb === 'accept_proposal') route = 'contract';
else if (cb === 'decline_proposal') route = 'negotiate';
else if (lead.state === 'awaiting_questionnaire' && text) route = 'questionnaire_step';
else if (orderIntent) route = 'start_questionnaire';
else if (lead.state === 'proposal_sent' && yes) route = 'contract';
return [{ json: { route, lead_id: lead.id, state: lead.state, chat_id: norm.chat_id, text: norm.text, first_name: norm.first_name } }];

const facts = $input.all().map(i => i.json.fact).filter(Boolean).join('\n- ');
const r = $('🚦 Роутер состояний').first().json;
const system = 'Ты — вежливый консультант аудиторской компании. Отвечай кратко (2-6 предложений), по-русски, без markdown. Отвечай СТРОГО на основе базы знаний ниже; если ответа там нет — скажи, что уточнишь у специалиста, и предложи оставить вопрос. Точную цену не называй — объясни, от чего зависит, и предложи пройти короткую анкету. В конце мягко предложи заказать аудит (кнопка под сообщением).\n\nБАЗА ЗНАНИЙ:\n- ' + facts;
const user = r.text || 'Здравствуйте';
return [{ json: { chat_id: r.chat_id, body: JSON.stringify({ model: 'llama-3.3-70b-versatile', temperature: 0.3, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] }) } }];

const meta = $('🧠 Запрос FAQ').first().json;
let answer = $json.choices?.[0]?.message?.content || '';
answer = String(answer).replace(/```/g, '').trim();
if (!answer) answer = 'Извините, не получилось ответить автоматически 🙈 Специалист свяжется с вами. А пока можете заказать аудит кнопкой ниже.';
return [{ json: { chat_id: meta.chat_id, answer } }];

