// Анкета по шагам. ID полей — из Sample_Audit_Questionnaire.md (их читает движок цены).
const QUESTIONS = [
  { id: 'company_name', text: 'Вопрос 1/12. Название вашей компании?', type: 'text' },
  { id: 'contact_name', text: 'Вопрос 2/12. Контактное лицо (ФИО, должность)?', type: 'text' },
  { id: 'email', text: 'Вопрос 3/12. Email для связи?', type: 'text' },
  { id: 'phone', text: 'Вопрос 4/12. Телефон?', type: 'text' },
  { id: 'audit_type', text: 'Вопрос 5/12. Какой аудит нужен? Ответьте цифрой:\n1 — Обязательный\n2 — Инициативный\n3 — Аудит недропользователя\n4 — Налоговый\n5 — Due diligence', type: 'choice', options: { '1': 'statutory', '2': 'voluntary', '3': 'subsoil', '4': 'tax', '5': 'due_diligence' } },
  { id: 'standard', text: 'Вопрос 6/12. Стандарт отчётности? Ответьте цифрой:\n1 — НСФО\n2 — МСФО', type: 'choice', options: { '1': 'nsfo', '2': 'ifrs' } },
  { id: 'years', text: 'Вопрос 7/12. Сколько лет (периодов) нужно проверить? Напишите число, например 1.', type: 'number' },
  { id: 'deadline_days', text: 'Вопрос 8/12. За сколько дней нужен результат? Напишите число, например 60 (менее 30 — срочный тариф).', type: 'number' },
  { id: 'revenue_band', text: 'Вопрос 9/12. Годовая выручка? Ответьте цифрой:\n1 — до ₸100 млн\n2 — ₸100 млн – 1 млрд\n3 — ₸1–10 млрд\n4 — свыше ₸10 млрд', type: 'choice', options: { '1': 'lt_100m', '2': '100m_1b', '3': '1b_10b', '4': 'gt_10b' } },
  { id: 'employees', text: 'Вопрос 10/12. Численность сотрудников? Ответьте цифрой:\n1 — до 50\n2 — 50–250\n3 — более 250', type: 'choice', options: { '1': 'lt_50', '2': '50_250', '3': 'gt_250' } },
  { id: 'entities', text: 'Вопрос 11/12. Сколько юридических лиц нужно проверить (консолидация)? Напишите число, например 1.', type: 'number' },
  { id: 'notes', text: 'Вопрос 12/12. Что ещё нам важно знать? (или напишите «нет»)', type: 'text' }
];
const row = $json;
const r = $('🚦 Роутер состояний').first().json;
const step = row.current_step ?? 0;
const q = QUESTIONS[step];
const answers = typeof row.answers === 'string' ? JSON.parse(row.answers) : (row.answers || {});
const text = (r.text || '').trim();
let valid = true;
let value = text;
if (q.type === 'choice') { const key = text.replace(/[^0-9]/g, ''); value = q.options[key]; if (!value) valid = false; }
else if (q.type === 'number') { const n = parseInt(text.replace(/[^0-9]/g, ''), 10); if (isNaN(n)) valid = false; else value = n; }
if (!valid) {
  return [{ json: { response_id: row.id, chat_id: r.chat_id, lead_id: r.lead_id, answers: JSON.stringify(answers), current_step: step, completed: false, done: false, message: 'Не понял ответ 🙈 Попробуйте ещё раз.\n\n' + q.text } }];
}
answers[q.id] = value;
if (q.id === 'audit_type') answers['is_subsoil'] = value === 'subsoil';
const next = step + 1;
const done = next >= QUESTIONS.length;
return [{ json: { response_id: row.id, chat_id: r.chat_id, lead_id: r.lead_id, answers: JSON.stringify(answers), current_step: next, completed: done, done, message: done ? 'Спасибо! Анкета заполнена ✅ Считаю стоимость — это займёт меньше минуты…' : QUESTIONS[next].text } }];

